import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("renaming a vendor to another vendor's name, in any case, is refused", { tag: "@LIF-10" }, async ({ apiAs, factory }) => {
  // Arrange
  const atlasName = uniqueName("Atlas Freight");
  const borealisName = uniqueName("Borealis Freight");
  const atlas = await factory.vendor({ as: "member", name: atlasName });
  const borealis = await factory.vendor({ as: "member", name: borealisName });
  const member = await apiAs("member");

  // Act
  const response = await member.patch(`/api/vendors/${borealis.id}`, {
    data: { name: atlasName.toUpperCase() },
  });

  // Assert
  const body = await expectStatus<{ error: { code: string } }>(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");

  // Assert the stored outcome: the vendor keeps its name.
  const stored = await expectStatus<{ id: string; name: string }>(
    await member.get(`/api/vendors/${borealis.id}`),
    200,
  );
  expect(stored.id).toBe(borealis.id);
  expect(stored.name).toBe(borealisName);
  expect(atlas.name).toBe(atlasName);
});
